// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(uint256 amount, bytes calldata data) public {
        vm.assume(amount > 0);
        address owner = address(this);
        Receiver recv = new Receiver();
        uint256 recvBalBefore = address(recv).balance;
        vm.deal(owner, amount);
        vm.prank(owner);
        c.Command{value: amount}(address(recv), data);
        uint256 recvBalAfter = address(recv).balance;
        assertTrue(recvBalAfter - recvBalBefore == amount);
    }
}
contract Receiver {
    fallback() external payable {}
}
